using System;using System.Collections.Generic;using System.IO;using Ashfall.Core;using Ashfall.Modules.Networking;using Ashfall.Modules.Construction;using Ashfall.Modules.ConstructionCandidate;
namespace Ashfall.Integration.Playable.Networking {
 public sealed partial class R24LanLobby {
  const string BuildCommand="playable.build.place/1",PanelFeature="playable.build.panel/1";IConstructionWorld constructionWorld;CandidateService sharedConstruction;double constructionAt;long constructionRevision,receivedPanelSequence=-1;
  readonly HashSet<string> dismantledPanels=new HashSet<string>(StringComparer.Ordinal);
  readonly Queue<string> dismantledOrder=new Queue<string>();
  public bool WasPanelDismantled(string id){return dismantledPanels.Contains(id);}
  void RememberDismantle(string id){if(dismantledPanels.Add(id))dismantledOrder.Enqueue(id);while(dismantledOrder.Count>256)dismantledPanels.Remove(dismantledOrder.Dequeue());}
  readonly Dictionary<string,PlacedPanel> sharedPanels=new Dictionary<string,PlacedPanel>(StringComparer.Ordinal);
  public PlacedPanel[] SharedPanels{get{var rows=new List<PlacedPanel>(sharedPanels.Values);rows.Sort(delegate(PlacedPanel a,PlacedPanel b){return String.CompareOrdinal(a.Id,b.Id);});return rows.ToArray();}}public long ConstructionRevision{get{return State==R24LanLobbyState.Hosting?constructionRevision:receivedPanelSequence;}}public string LastBuildRejection{get;private set;}
  sealed class ConstructionGate:IAuthorityGate {readonly R24LanLobby owner;internal ConstructionGate(R24LanLobby owner){this.owner=owner;}public RuleResult Validate(CommandContext c){return c.IsAuthority&&c.SessionId==owner.SessionId&&c.AuthorityEpoch==owner.Epoch&&owner.HasMember(c.ActorId)?RuleResult.Accept():RuleResult.Reject("host-member-context");}}
  sealed class ConstructionWorld:IConstructionWorld {readonly R24LanLobby owner;internal ConstructionWorld(R24LanLobby owner){this.owner=owner;}public bool HasStaticContact(Panel panel,float tolerance){return owner.constructionWorld.HasStaticContact(panel,tolerance);}public bool IsBuried(Panel panel){return owner.constructionWorld.IsBuried(panel);}public bool HasLineOfSight(string actor,Float3 a,Float3 b){return owner.constructionWorld.HasLineOfSight(actor,a,b);}public string Clearance(Panel panel,string actor){string reason=owner.constructionWorld.Clearance(panel,actor);if(!String.IsNullOrEmpty(reason))return reason;var half=CandidateGeometry.HalfSize(panel);foreach(var member in owner.sessions.CaptureMembers()){R24LanRawTrackingSample raw;if(!owner.Fresh(member.ActorId,owner.clock.Now,out raw))continue;var root=raw.Pose.Root.Position;float top=Math.Max(root.Y+.5f,raw.Pose.Head.Position.Y+.15f);if(Math.Abs(root.X-panel.Center.X)<half.X+.27f&&Math.Abs(root.Z-panel.Center.Z)<half.Z+.27f&&root.Y<panel.Center.Y+half.Y&&top>panel.Center.Y-half.Y)return "player_clearance";}return "";}}
  public void BindConstructionWorld(IConstructionWorld world){Check();if(State!=R24LanLobbyState.Hosting||world==null||constructionWorld!=null)throw new InvalidOperationException("One host construction world");constructionWorld=world;}
  void ClearConstruction(){sharedConstruction=null;sharedPanels.Clear();dismantledPanels.Clear();dismantledOrder.Clear();constructionAt=clock.Now;receivedPanelSequence=-1;foreach(var peer in peers.Values){peer.Panels.Clear();peer.SentPanels.Clear();}}
  public bool RequestBuild(int hand){return RequestBuild(hand,0);}
  public bool RequestBuild(int hand,int tier){return RequestBuild(hand,tier,0);}
  public bool RequestBuild(int hand,int tier,int variant){return RequestBuild(hand,tier,variant,false);}
  public bool RequestBuild(int hand,int tier,int variant,bool dismantle){Check();if(hand<0||hand>1||tier<0||tier>2||variant<0||variant>3)return false;if(State==R24LanLobbyState.Hosting)return ApplyBuild(OwnActor,hand,tier,variant,dismantle);return State==R24LanLobbyState.Connected&&QueueGameCommand(BuildCommand,new[]{(byte)hand,(byte)tier,(byte)variant,(byte)(dismantle?1:0)});}
  CommandContext ConstructionContext(string actor){long id=checked(++tick);return new CommandContext(SessionId,actor,"lan-build/"+id,id,Epoch,true);}
  bool ApplyBuild(string actor,int hand,int tier,int variant,bool dismantle){LastBuildRejection=null;if(dismantle&&!GameplayRules.BuildPieces){LastBuildRejection="dismantle_disabled";return false;}if(variant<0||variant>3||!GameplayRules.BuildPieces&&variant!=0){LastBuildRejection="variant";return false;}if(tier<0||tier>2||!GameplayRules.BuildPieces&&tier!=0){LastBuildRejection="tier";return false;}CombatActor owner;R24LanRawTrackingSample raw;var member=sessions.Get(actor);if(!InventoryLive||ControlsBlocked(actor)||!GameplayRules.Builds||constructionWorld==null||hand<0||hand>1||member==null||member.Life!=Ashfall.Modules.Sessions.SessionLife.Alive||!combat.TryGetValue(actor,out owner)||!Fresh(actor,clock.Now,out raw)||(raw.Pose.Flags&(hand==0?2:4))==0||raw.Pose.Paddles||owner.LastBuildPose>=raw.Sequence){LastBuildRejection="actual-live-build-pose";return false;}if(HandOccupied(actor,hand)||GrenadeHandOccupied(actor,hand)){LastBuildRejection="occupied-weapon-hand";return false;}FoodPreparation food;if(foodPreparations.TryGetValue(actor,out food)&&food.Hand==hand){LastBuildRejection="occupied-hand";return false;}
   var pose=hand==0?raw.Pose.Left:raw.Pose.Right;if(rawWorldClear==null||!rawWorldClear(raw.Pose.Head.Position,pose.Position)){LastBuildRejection="head-hand-world";return false;}if(sharedConstruction==null){sharedConstruction=new CandidateService(SessionId,Epoch,new ConstructionGate(this),new ConstructionWorld(this),GameplayRules.InfiniteBuilds);constructionAt=clock.Now;}
   var builder=new BuilderState(pose.Position,Rotate(pose.Rotation,new Float3(0,-1,0)),raw.Pose.Head.Position,true,true,tier,GameplayRules.BuildPieces,variant);
   if(dismantle){var target=sharedConstruction.DismantleTarget(actor,builder);if(target==null){LastBuildRejection="dismantle_target";return false;}
    var direction=Normalize(builder.Direction);float reach=Geometry.Ray(builder.Origin,direction,target.Shape,6,0);
    if(!rawWorldClear(builder.Origin,Ashfall.Integration.Playable.HandsWeapons.R23WeaponPoseMath.Add(builder.Origin,Ashfall.Integration.Playable.HandsWeapons.R23WeaponPoseMath.Scale(direction,Math.Max(0,reach-.05f))))){LastBuildRejection="dismantle_world";return false;}}
   var removed=dismantle?sharedConstruction.DismantleTarget(actor,builder):null;
   CandidateService.PreparedChange change;var c=ConstructionContext(actor);
   var result=dismantle?sharedConstruction.PrepareDismantle(new ConstructionCommand(c,c.Tick),builder,out change):sharedConstruction.PreparePlace(new ConstructionCommand(c,c.Tick),builder,out change);if(!result.Accepted){LastBuildRejection=result.Reason;return false;}try{if(!change.Validate()||change.Cost>owner.Builds){LastBuildRejection="build-charge-or-state";return false;}owner.Builds-=change.Cost;owner.LastBuildPose=raw.Sequence;change.CommitValidated();if(removed!=null)RememberDismantle(removed.Id);PublishConstruction();return true;}finally{change.Abort();}
  }
  void TickConstruction(){if(State!=R24LanLobbyState.Hosting||sharedConstruction==null)return;double elapsed=Math.Max(0,clock.Now-constructionAt);constructionAt=clock.Now;CandidateService.PreparedChange change;var result=sharedConstruction.PrepareAdvance((float)elapsed,!InventoryLive,out change);if(result.Accepted&&change!=null){if(change.Validate())change.CommitValidated();change.Abort();PublishConstruction();}}
  // Every room source (bullets, mounted guns, melee, blasts) passes RAW damage here; this is the only place the BUILD DAMAGE rule is applied.
  void DamageSharedPanel(string id,float damage){if(State!=R24LanLobbyState.Hosting||sharedConstruction==null||!InventoryLive||damage<=0||Single.IsNaN(damage)||Single.IsInfinity(damage))return;damage=GameplayRules.ScaleBuildDamage(damage);if(damage<=0||Single.IsInfinity(damage))return;CandidateService.PreparedChange change;var result=sharedConstruction.PrepareDamage(ConstructionContext(OwnActor),id,damage,sharedConstruction.Revision,out change);if(result.Accepted&&change!=null){if(change.Validate())change.CommitValidated();change.Abort();PublishConstruction();}}
  void PublishConstruction(){var next=new Dictionary<string,PlacedPanel>(StringComparer.Ordinal);foreach(var panel in sharedConstruction.Snapshot())next[panel.Id]=panel;bool changed=false;foreach(var old in sharedPanels)if(!next.ContainsKey(old.Key)){changed=true;foreach(var peer in peers.Values)if(peer.Admitted){if(peer.SentPanels.Contains(old.Key))peer.Panels[old.Key]=null;else peer.Panels.Remove(old.Key);}}
   foreach(var panel in next){PlacedPanel old;if(!sharedPanels.TryGetValue(panel.Key,out old)||old.Shape.Tier!=panel.Value.Shape.Tier||old.Health!=panel.Value.Health||!old.Shape.Center.Equals(panel.Value.Shape.Center)){changed=true;foreach(var peer in peers.Values)if(peer.Admitted)peer.Panels[panel.Key]=panel.Value;}}
   if(changed){sharedPanels.Clear();foreach(var panel in next)sharedPanels[panel.Key]=panel.Value;constructionRevision++;}
  }
  byte[] PanelFrame(string id,PlacedPanel panel,long sequence){using(var m=new MemoryStream())using(var w=new BinaryWriter(m,Utf8)){Write(w,id,128);w.Write(panel!=null);if(panel!=null){Write(w,panel.Owner,64);w.Write(panel.Shape.Kind=="wall");w.Write((byte)panel.Shape.Axis);w.Write((byte)panel.Shape.Tier);w.Write((byte)panel.Shape.Variant);w.Write(panel.Shape.Center.X);w.Write(panel.Shape.Center.Y);w.Write(panel.Shape.Center.Z);w.Write(panel.Shape.LowerSupport);w.Write(panel.Shape.Distance);w.Write(panel.Health);}else w.Write((byte)(WasPanelDismantled(id)?1:0));return Packet(PacketKind.Snapshot,PanelFeature,OwnActor,m.ToArray(),sequence);}}
  void ReadPanel(Packet packet){if(packet.Sequence<=receivedPanelSequence||packet.Sequence<1||packet.BaseSequence!=-1)return;try{using(var m=new MemoryStream(packet.Payload,false))using(var r=new BinaryReader(m,Utf8)){string id=Read(r,128);bool present=r.ReadBoolean();PlacedPanel panel=null;if(present){string owner=Read(r,64),kind=r.ReadBoolean()?"wall":"floor";int axis=r.ReadByte(),tier=r.ReadByte(),variant=r.ReadByte();var at=new Float3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());bool support=r.ReadBoolean();float distance=r.ReadSingle(),health=r.ReadSingle();if(variant>3||kind=="floor"&&variant!=0||tier>2||axis>2||(kind=="wall")==(axis==1)||!at.IsFinite||Math.Abs(at.X)>100000||Math.Abs(at.Y)>100000||Math.Abs(at.Z)>100000||Single.IsNaN(distance)||distance<0||distance>10||Single.IsNaN(health)||health<=0||health>new Panel(kind,at,axis,support,distance,tier,variant).MaximumHealth||sharedPanels.Count>=256&&!sharedPanels.ContainsKey(id))return;panel=new PlacedPanel(id,owner,new Panel(kind,at,axis,support,distance,tier,variant),health);}bool dismantled=false;if(!present){int reason=r.ReadByte();if(reason>1)return;dismantled=reason==1;}if(m.Position!=m.Length)return;receivedPanelSequence=packet.Sequence;if(dismantled)RememberDismantle(id);if(panel==null)sharedPanels.Remove(id);else sharedPanels[id]=panel;}}catch(InvalidDataException){}catch(IOException){}catch(ArgumentException){}}
  void FlushPanels(string connection,Peer peer){var sent=new List<string>();int budget=16;foreach(var entry in peer.Panels){if(entry.Value!=null)continue;if(budget--<=0||!Send(connection,PanelFrame(entry.Key,null,checked(++peer.PanelSequence))))break;peer.SentPanels.Remove(entry.Key);sent.Add(entry.Key);}foreach(string id in sent)peer.Panels.Remove(id);sent.Clear();foreach(var entry in peer.Panels){if(budget--<=0||!Send(connection,PanelFrame(entry.Key,entry.Value,checked(++peer.PanelSequence))))break;peer.SentPanels.Add(entry.Key);sent.Add(entry.Key);}foreach(string id in sent)peer.Panels.Remove(id);}
  static float BoxRay(Float3 origin,Float3 direction,Panel panel,float range,float margin=0){return Geometry.Ray(origin,direction,panel,range,margin);}
  string NearestSharedPanel(Float3 origin,Float3 direction,float range,out float distance){distance=range;string id=null;foreach(var panel in sharedPanels.Values){float d=BoxRay(origin,direction,panel.Shape,range);if(d<distance||d==distance&&(id==null||String.CompareOrdinal(panel.Id,id)<0)){distance=d;id=panel.Id;}}return id;}
  bool ConstructionRayClear(Float3 from,Float3 to){var delta=Sub(to,from);float range=(float)Math.Sqrt(Distance2(from,to));if(range<.0001f)return true;float distance;return NearestSharedPanel(from,Normalize(delta),range,out distance)==null;}
 }
